public class GymTiers { static class Gym{String id;int sessions;Gym(String i){id=i;}void attend(){sessions++;}} static class Premium extends Gym{Premium(String i){super(i);}} static class Elite extends Premium{Elite(String i){super(i);}} static class Group extends Gym{Group(String i){super(i);}} static String type(Gym g){if(g instanceof Elite)return "Multilevel descendant (3 generations deep)";if(g instanceof Group)return "Hierarchical sibling (independent branch)";if(g instanceof Premium)return "Premium Member";return "Standard Member";} static int total(Gym[]a){int t=0;for(Gym g:a)t+=g.sessions;return t;} public static void main(String[]x){System.out.println(type(new Elite("E")));}}
